function resolveSeasonTheme(seasonIdValue) {
  const raw = String(seasonIdValue || "").trim();
  const normalized = raw === "true_spring" ? "warm_spring" : raw;

  return (
    DIART_SEASON_THEMES[raw] ||
    DIART_SEASON_THEMES[normalized] ||
    Object.freeze({
      background: "#FBF7F1",
      ink: "#2C1A13",
      muted: "#6F5A4C",
      line: "#DCCFC2",
      panel: "#FFFDFC"
    })
  );
}

function replaceAllLiteral(source, from, to) {
  return String(source || "").split(from).join(to);
}

function buildThemedSources(seasonIdValue) {
  const theme = resolveSeasonTheme(seasonIdValue);
  const themed = { ...EMBEDDED_SOURCES };

  // PAGE 1 background only. Logo code and logo URL are intentionally untouched.
  themed["passport/page1.js"] = replaceAllLiteral(
    themed["passport/page1.js"],
    'safe.backgroundColor || "#FBF7F1"',
    `safe.backgroundColor || "${theme.background}"`
  );

  themed["passport/page1.js"] = replaceAllLiteral(
    themed["passport/page1.js"],
    'safe.accentColor || "#8A4E25"',
    `safe.accentColor || "${theme.ink}"`
  );

  const page1Modules = [
    "passport/components/header_block_approved.js",
    "passport/components/analysis_block_adaptive_icons.js",
    "passport/components/natural_palette_block_approved.js",
    "passport/components/nearest_seasons_block_balanced.js",
    "passport/components/information_panel_block_approved.js",
    "passport/components/footer_block_approved.js"
  ];

  for (const moduleId of page1Modules) {
    let source = themed[moduleId];

    source = replaceAllLiteral(source, "#2C1A13", theme.ink);
    source = replaceAllLiteral(source, "#24160F", theme.ink);

    source = replaceAllLiteral(source, "#6F5A4C", theme.muted);
    source = replaceAllLiteral(source, "#746052", theme.muted);
    source = replaceAllLiteral(source, "#7B6758", theme.muted);
    source = replaceAllLiteral(source, "#8B7769", theme.muted);
    source = replaceAllLiteral(source, "#5F4D42", theme.muted);

    source = replaceAllLiteral(source, "#DCCFC2", theme.line);
    source = replaceAllLiteral(source, "#E7DDD3", theme.line);
    source = replaceAllLiteral(source, "#DED1C4", theme.line);

    source = replaceAllLiteral(source, "#FFFDFC", theme.panel);

    themed[moduleId] = source;
  }

  return themed;
}

function normalizeFooterSeasonId(value) {
  const id = String(value || "").trim();
  return id === "true_spring" ? "warm_spring" : id;
}

function resolveFooterOrnamentUrl(seasonId, assetsBaseUrl) {
  const slug = normalizeFooterSeasonId(seasonId);
  if (!slug) return "";

  const base = String(
    assetsBaseUrl ||
    "https://raw.githubusercontent.com/nuuu1334-droid/DiArt-Passport-/refs/heads/main/assets"
  ).replace(/\/+$/, "");

  return `${base}/footer_ornaments/${slug}/ornament.png`;
}

function runPipeline(input) {
  const engineResult = parseMaybeJson(input.engineResult, "engineResult");
  const paletteDatabase = parseMaybeJson(input.paletteDatabase, "paletteDatabase");
  const masterColorLibrary = parseMaybeJson(input.masterColorLibrary, "masterColorLibrary");
  const pinManifest = parseMaybeJson(input.pinManifest, "pinManifest");
  const analysisIconsManifest = parseMaybeJson(
    input.analysisIconsManifest,
    "analysisIconsManifest"
  );
  const infoIconsManifest = parseMaybeJson(
    input.infoIconsManifest,
    "infoIconsManifest"
  );
  const photoSamples = parseMaybeJson(input.photoSamples, "photoSamples", {});

  const seasonId = unwrapEngineForSeason(engineResult);
  const themedSources = buildThemedSources(seasonId);
  const modules = createModuleSystem(themedSources);
  const paletteResolver = modules.load("passport/palette_resolver.js");
  const adapter = modules.load("passport/passport_input_adapter.js");
  const builder = modules.load("passport/passport_builder.js");
  const assetRegistry = modules.load("passport/asset_registry.js");
  const paletteResult = paletteResolver.resolvePalette({
    paletteDatabase,
    masterColorLibrary,
    seasonId
  });

  if (!paletteResult || paletteResult.ok !== true) {
    throw new Error(
      paletteResult && paletteResult.error && paletteResult.error.message
        ? paletteResult.error.message
        : "Palette Resolver завершился с ошибкой."
    );
  }

  const adapterResult = adapter.main({
    engineResult,
    paletteResult,
    pinManifest,
    photoUrl: input.photoUrl,
    logoUrl: "https://raw.githubusercontent.com/nuuu1334-droid/DiArt-Passport-/main/assets/logos/DiArt_logo_transparent.png",
    photoSamples,
    aiModel: input.aiModel,
    clientName: input.clientName,
    createdAt: input.createdAt,
    passportId: input.passportId,
    harmonyGuide: input.harmonyGuide,
    importantNote: input.importantNote
  });

  if (!adapterResult || adapterResult.ok !== true) {
    throw new Error(
      adapterResult && adapterResult.error && adapterResult.error.message
        ? adapterResult.error.message
        : "Passport Input Adapter завершился с ошибкой."
    );
  }

   if (
    !adapterResult.result.assets ||
    typeof adapterResult.result.assets !== "object" ||
    Array.isArray(adapterResult.result.assets)
  ) {
    adapterResult.result.assets = {};
  }

  const SEASON_FALLBACK_COLORS = Object.freeze({
    light_spring: "#8FB36A",
    true_spring: "#F2A900",
    warm_spring: "#F2A900",
    bright_spring: "#FF5C57",
    light_summer: "#87A9C4",
    true_summer: "#5F7E9B",
    soft_summer: "#9A6C9D",
    soft_autumn: "#C79B57",
    true_autumn: "#D85F00",
    deep_autumn: "#5B2A0C",
    bright_winter: "#B0004F",
    true_winter: "#17345C",
    deep_winter: "#1F1F1F"
  });

  const manifestPins =
    pinManifest && Array.isArray(pinManifest.pins)
      ? pinManifest.pins
      : [];

  function resolveSeasonColor(seasonIdValue) {
    const normalized =
      assetRegistry &&
      typeof assetRegistry.normalizeSeasonId === "function"
        ? assetRegistry.normalizeSeasonId(seasonIdValue)
        : String(seasonIdValue || "").trim();

    const fromManifest = manifestPins.find(
      item =>
        item &&
        String(item.slug || "").trim() === normalized
    );

    if (
      fromManifest &&
      typeof fromManifest.color === "string" &&
      fromManifest.color.trim()
    ) {
      return fromManifest.color.trim();
    }

    return (
      SEASON_FALLBACK_COLORS[String(seasonIdValue || "").trim()] ||
      SEASON_FALLBACK_COLORS[normalized] ||
      "#8A4E25"
    );
  }

  if (Array.isArray(adapterResult.result.top3)) {
    adapterResult.result.top3 = adapterResult.result.top3.map(item => {
      const seasonIdValue =
        item && item.season_id
          ? String(item.season_id)
          : "";

      return {
        ...item,
        color: resolveSeasonColor(seasonIdValue),
        pin_url:
          assetRegistry &&
          typeof assetRegistry.pin === "function"
            ? assetRegistry.pin(seasonIdValue)
            : ""
      };
    });
  }

  adapterResult.result.assets.active_pin =
    assetRegistry &&
    typeof assetRegistry.pin === "function"
      ? assetRegistry.pin(seasonId)
      : "";

  adapterResult.result.backgroundColor =
    resolveSeasonTheme(seasonId).background;

  adapterResult.result.accentColor =
    resolveSeasonColor(seasonId);

  adapterResult.result.assets.analysis_icons_manifest =
    analysisIconsManifest;

  adapterResult.result.assets.info_icons_manifest =
    infoIconsManifest;

  adapterResult.result.assets.base_url =
    String(
      input.assetsBaseUrl ||
      "https://raw.githubusercontent.com/nuuu1334-droid/DiArt-Passport-/refs/heads/main/assets"
    ).replace(/\/+$/, "");

  adapterResult.result.assets.footer_ornament =
    resolveFooterOrnamentUrl(
      seasonId,
      adapterResult.result.assets.base_url
    );

  // Abstract-minimalist system: do not reuse the full-width footer ornament
  // inside Page 2's former botanical decoration slot.
  adapterResult.result.assets.botanical_branch = "";

  const result = builder.buildPassport(adapterResult);

  if (!result || result.ok !== true) {
    throw new Error(
      result && result.error && result.error.message
        ? result.error.message
        : "Passport Builder завершился с ошибкой."
    );
  }

  return {
    ok: true,
    stage: "diart_passport_bundle_completed",
    bundle_version: BUNDLE_VERSION,
    asset_policy: "official_assets_only",
    ...result
  };
}

function main(input) {
  try {
    if (!isObject(input)) {
      throw new Error("Make Code не передал объект input.");
    }

    return runPipeline(input);
  } catch (error) {
    return {
      ok: false,
      stage: "diart_passport_bundle_failed",
      bundle_version: BUNDLE_VERSION,
      error: {
        message:
          error && error.message
            ? error.message
            : "Неизвестная ошибка DiArt Passport Builder."
      }
    };
  }
}

return main(input);
